function buildOffer(p, now) {
  p = p || {};
  var R = 6371008.8, rad = Math.PI / 180;
  function polyAreaM2(pts) {
    var s = 0;
    for (var i = 0; i < pts.length; i++) {
      var a = pts[i], b = pts[(i + 1) % pts.length];
      s += (b[1] - a[1]) * rad * (2 + Math.sin(a[0] * rad) + Math.sin(b[0] * rad));
    }
    return Math.abs(s * R * R / 2);
  }
  function round10(x) { return Math.round(x / 10) * 10; }
  var txt = function (v) { return (v === undefined || v === null) ? '' : String(v).trim().slice(0, 500); };

  var problems = [];
  var name = txt(p.name), email = txt(p.email);
  if (!name) problems.push('Name fehlt');
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) problems.push('E-Mail ungültig');

  var modus = p.modus === 'polygon' ? 'polygon' : 'radius';
  var lat = Number(p.lat), lon = Number(p.lon), radius = Number(p.radius_m) || 0;
  var poly = Array.isArray(p.polygon) ? p.polygon.filter(function (q) {
    return Array.isArray(q) && isFinite(q[0]) && isFinite(q[1]);
  }).slice(0, 200) : [];
  var areaM2 = 0, geojson = '';
  if (modus === 'polygon' && poly.length >= 3) {
    areaM2 = polyAreaM2(poly);
    var ring = poly.map(function (q) { return [Number(q[1]), Number(q[0])]; });
    ring.push(ring[0]);
    geojson = JSON.stringify({ type: 'Polygon', coordinates: [ring] });
  } else if (modus === 'radius' && isFinite(lat) && isFinite(lon) && radius > 0) {
    areaM2 = Math.PI * radius * radius;
    geojson = JSON.stringify({ type: 'Point', coordinates: [lon, lat], radius_m: radius });
  } else {
    problems.push('Standort fehlt');
  }
  var ha = Math.round(areaM2 / 100) / 100;
  if (geojson && ha < 0.01) problems.push('Fläche sehr klein');
  if (ha > 200) problems.push('Fläche über 200 ha');

  var eilig = p.dringlichkeit === 'eilig';
  var von = '', bis = '', wochen = '';
  if (!problems.length) {
    // DEMO-ANNAHMEN: Preislogik hier anpassen
    var mid = 480;
    if (ha > 1) mid += 45 * (Math.min(ha, 20) - 1);
    if (ha > 20) mid += 25 * (ha - 20);
    if (eilig) mid *= 1.3;
    von = round10(mid * 0.85);
    bis = round10(mid * 1.25);
    if (ha <= 5) wochen = eilig ? '1–2' : '2–3';
    else if (ha <= 20) wochen = eilig ? '2–3' : '3–4';
    else wochen = eilig ? '3–4' : '4–6';
  }

  var wd = ['So', 'Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa'];
  var days = [], d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), 12));
  while (days.length < 3) {
    d = new Date(d.getTime() + 86400000);
    if (d.getUTCDay() !== 0 && d.getUTCDay() !== 6) days.push(d);
  }
  function fmt(x, t) {
    return wd[x.getUTCDay()] + ' ' + ('0' + x.getUTCDate()).slice(-2) + '.' + ('0' + (x.getUTCMonth() + 1)).slice(-2) + '. ' + t + ' Uhr';
  }
  var slots = [fmt(days[0], '10:00'), fmt(days[0], '14:30'), fmt(days[1], '10:00'), fmt(days[2], '14:30')];

  var nr = 'LBA-' + now.getUTCFullYear() + '-' + ('0000' + Math.floor(Math.random() * 10000)).slice(-4);
  var ok = problems.length === 0;
  return {
    projekt_nr: nr,
    eingang: now.toISOString().slice(0, 16).replace('T', ' ') + ' UTC',
    status: ok ? 'Neu' : 'Manuell prüfen',
    leistung: txt(p.leistung) || 'Luftbildauswertung',
    name: name, firma: txt(p.firma), email: email, telefon: txt(p.telefon),
    adresse: txt(p.adresse),
    lat: isFinite(lat) ? Math.round(lat * 1e6) / 1e6 : '',
    lon: isFinite(lon) ? Math.round(lon * 1e6) / 1e6 : '',
    modus: modus, radius_m: modus === 'radius' ? radius : '',
    flaeche_ha: ha,
    vorhaben: txt(p.vorhaben), baubeginn: txt(p.baubeginn),
    dringlichkeit: eilig ? 'eilig' : 'normal',
    preis_von: von, preis_bis: bis, bearbeitung_wochen: wochen,
    ruf_termine: slots.join(' | '),
    hinweis: ok ? '' : problems.join('; '),
    nachricht: txt(p.nachricht),
    geojson: geojson,
    ok: ok,
    sprache: /^(de|en|fr|nl)$/.test(p.sprache) ? p.sprache : 'de'
  };
}

// Eingang vom Formular: body.payload ist ein JSON-Text
let p = {};
try { p = JSON.parse($input.first().json.body.payload); } catch (e) {}
return [{ json: buildOffer(p, new Date()) }];

// Einfacher Schutz: nur mit richtigem Schlüssel gibt es Daten
